import React, { useEffect, useRef } from 'react';
import { View, Image, StyleSheet, Animated, Easing } from 'react-native';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from '../services/firebaseConfig';
import { LinearGradient } from 'expo-linear-gradient';

export default function SplashLogoScreen({ navigation }: any) {
  const opacity = useRef(new Animated.Value(0)).current;
  const progress = useRef(new Animated.Value(0)).current;
  // Valor da animação da bolinha
  const ballAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    // Animação da logo (mantida igual)
    Animated.timing(opacity, {
      toValue: 1,
      duration: 600,
      useNativeDriver: true,
    }).start();

    // Animação da barra de progresso (mantida igual)
    Animated.timing(progress, {
      toValue: 1,
      duration: 1600,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: false,
    }).start();

    // Inicia o loop da bolinha circulando
    Animated.loop(
      Animated.timing(ballAnim, {
        toValue: 1,
        duration: 1600,
        easing: Easing.linear,
        useNativeDriver: true,
      })
    ).start();

    // Verificação de autenticação e navegação (mantida integralmente)
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setTimeout(() => {
        if (user && user.emailVerified) {
          navigation.replace('Inicio');
        } else {
          navigation.replace('Login');
        }
      }, 1800);
    });

    return () => unsubscribe();
  }, [navigation, opacity, progress, ballAnim]);

  const widthInterpolate = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });

  // Interpolação para mover a bolinha de um lado para o outro
  const ballTranslateX = ballAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [-10, 210], // Começa à esquerda e termina à direita
  });

  // Interpolação para mudar a cor da bolinha (azul, verde, amarelo, vermelho)
  const ballColor = ballAnim.interpolate({
    inputRange: [0, 0.25, 0.5, 0.75, 1],
    outputRange: ['#007AFF', '#34C759', '#FF9500', '#FF3B30', '#007AFF'],
  });

  return (
    <View style={styles.container}>
      <Animated.Image
        source={require('../assets/logo.png')}
        style={[styles.logo, { opacity }]}
        resizeMode="contain"
      />
      <View style={styles.progressBarContainer}>
        <Animated.View style={[styles.progressBarWrapper, { width: widthInterpolate }]}>
          <LinearGradient
            colors={['#c6f321', '#d26919', '#a1430d']}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.progressBar}
          />
        </Animated.View>
      </View>
      {/* Bolinha que circula nas cores do Windows */}
      <Animated.View
        style={[
          styles.ball,
          {
            transform: [{ translateX: ballTranslateX }],
            backgroundColor: ballColor,
          },
        ]}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#18182a',
    justifyContent: 'center',
    alignItems: 'center',
  },
  logo: {
    width: 180,
    height: 180,
    marginBottom: 32,
  },
  progressBarContainer: {
    width: 200,
    height: 10,
    borderRadius: 5,
    backgroundColor: '#23243a',
    overflow: 'hidden',
    marginTop: 8,
  },
  progressBarWrapper: {
    height: '100%',
    borderRadius: 5,
  },
  progressBar: {
    height: '100%',
    borderRadius: 5,
  },
  // Estilo da bolinha
  ball: {
    width: 20,
    height: 20,
    borderRadius: 10,
    position: 'absolute',
    bottom: 40,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.5,
    shadowRadius: 2,
  },
});